-- V36: Culture Articles and Categories Management (Learner & Admin)

CREATE TABLE IF NOT EXISTS culture_categories (
    id VARCHAR(100) NOT NULL PRIMARY KEY,
    name VARCHAR(255) NOT NULL,
    name_vi VARCHAR(255),
    name_en VARCHAR(255),
    slug VARCHAR(100),
    icon VARCHAR(50) DEFAULT '🏮',
    description VARCHAR(1000),
    display_order INT NOT NULL DEFAULT 0,
    created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    updated_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6)
);

CREATE TABLE IF NOT EXISTS culture_articles (
    id VARCHAR(100) NOT NULL PRIMARY KEY,
    title VARCHAR(500) NOT NULL,
    title_vi VARCHAR(500),
    title_en VARCHAR(500),
    subtitle VARCHAR(1000),
    subtitle_vi VARCHAR(1000),
    subtitle_en VARCHAR(1000),
    summary TEXT,
    summary_vi TEXT,
    summary_en TEXT,
    content LONGTEXT,
    content_vi LONGTEXT,
    content_en LONGTEXT,
    category_id VARCHAR(100),
    category_name VARCHAR(255),
    region VARCHAR(100) DEFAULT 'Toàn quốc',
    destination VARCHAR(100) DEFAULT 'Toàn quốc',
    destination_id VARCHAR(100) DEFAULT 'all',
    author VARCHAR(255) DEFAULT 'Biên tập viên Hola',
    author_role VARCHAR(255),
    author_role_vi VARCHAR(255),
    author_role_en VARCHAR(255),
    read_time VARCHAR(100) DEFAULT '5 phút đọc',
    read_time_vi VARCHAR(100) DEFAULT '5 phút đọc',
    read_time_en VARCHAR(100) DEFAULT '5 min read',
    cover_image VARCHAR(1000),
    status VARCHAR(50) NOT NULL DEFAULT 'PUBLISHED',
    is_featured BOOLEAN NOT NULL DEFAULT FALSE,
    views BIGINT NOT NULL DEFAULT 0,
    published_at TIMESTAMP(6) NULL,
    useful_phrases JSON,
    related_article_ids JSON,
    created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    updated_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
    CONSTRAINT fk_culture_article_category FOREIGN KEY (category_id) REFERENCES culture_categories(id) ON DELETE SET NULL
);

CREATE INDEX idx_culture_articles_status_featured ON culture_articles(status, is_featured, published_at);
CREATE INDEX idx_culture_articles_category ON culture_articles(category_id, status);
CREATE INDEX idx_culture_articles_destination ON culture_articles(destination_id, status);

